/*
 * Patina — Aqua structure × millennium colour tones.
 * Source of truth: /DESIGN.md (Google DESIGN.md format). Keep the two in sync.
 *
 * Structure = Mac OS X Aqua (2000–2005): pinstripes, traffic lights, gel
 * buttons, brushed metal, a translucent Dock. It never changes.
 * Tone = the hue of everything gel and the wallpaper. Switch with
 * data-tone="pink|aqua|lime|tangerine|grape" on <html>. Pink is default.
 */

:root {
  color-scheme: light;

  /* ── Aqua constants (never toned) ─────────────────────────────── */
  --y2k-ink: #000000;
  --y2k-ink-secondary: #4b4b4b;
  --y2k-ink-disabled: #999999;
  --y2k-ink-dim: #7f7f7f;
  --y2k-window-bg: #ececec;
  --y2k-window-border: rgba(0, 0, 0, 0.4);
  --y2k-window-border-inactive: rgba(0, 0, 0, 0.08);
  --y2k-titlebar-border: rgba(0, 0, 0, 0.3);
  --y2k-titlebar-border-inactive: rgba(0, 0, 0, 0.2);
  --y2k-separator: rgba(0, 0, 0, 0.2);
  --y2k-input-bg: #ffffff;
  --y2k-input-border: rgba(0, 0, 0, 0.2);
  --y2k-os-blue: #2765ca;

  /* ── Type ─────────────────────────────────────────────────────── */
  --y2k-font-ui: "Lucida Grande", "LucidaGrande", "AquaKana", var(--font-lato, "Lato"), "Lucida Sans Unicode", "Hiragino Sans", "Hiragino Sans GB", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --y2k-font-wordmark: var(--font-eb-garamond, "EB Garamond"), "Apple Garamond", Garamond, "Times New Roman", serif;
  --y2k-font-mono: Monaco, ui-monospace, Menlo, "Courier New", monospace;

  /* ── Pinstripes: 1.5px of #ececec then 2.5px of white, 4px period ─ */
  --y2k-pinstripe: repeating-linear-gradient(0deg, transparent 0px, transparent 1.5px, rgba(255, 255, 255, 0.85) 1.5px, rgba(255, 255, 255, 0.85) 4px), linear-gradient(#ececec, #ececec);
  --y2k-pinstripe-titlebar: linear-gradient(to bottom, rgba(255, 255, 255, 0.3) 0%, rgba(219, 219, 219, 0.6) 70%, rgba(206, 206, 206, 0.7) 100%);
  /* Inactive title bar: lighter, desaturated pinstripe with NO opaque base —
     it composites over the desktop, so a backgrounded window shows the
     wallpaper faintly through its title bar (real Aqua behaviour). */
  --y2k-pinstripe-inactive: repeating-linear-gradient(0deg, transparent 0px, transparent 1.5px, rgba(255, 255, 255, 0.45) 1.5px, rgba(255, 255, 255, 0.45) 4px);
  /* --y2k-window-bg at 55% alpha, so the inactive title bar tracks the same
     base colour as the active one instead of a hand-copied #ececec. */
  --y2k-titlebar-inactive-bg: color-mix(in srgb, var(--y2k-window-bg) 55%, transparent);
  --y2k-pinstripe-menubar: repeating-linear-gradient(0deg, transparent 0px, transparent 1.5px, rgba(255, 255, 255, 0.55) 1.5px, rgba(255, 255, 255, 0.55) 4px);
  --y2k-menubar-bg: linear-gradient(to bottom, #f8f8f8, #d4d4d4);
  --y2k-dock-surface: rgba(248, 248, 248, 0.75);
  --y2k-metal: url("data:image/png;base64,");

  /* ── Gel (buttons, popups, lights) ─────────────────────────────── */
  --y2k-gel-white: linear-gradient(rgba(160, 160, 160, 0.625), rgba(255, 255, 255, 0.625));
  --y2k-gel-white-shadow: 0 2px 3px rgba(0, 0, 0, 0.2), 0 1px 1px rgba(0, 0, 0, 0.3), inset 0 1px 2px rgba(0, 0, 0, 0.4), inset 0 2px 3px 1px #bbbbbb;
  --y2k-gel-white-shadow-active: var(--y2k-gel-white-shadow), 0 0 3px rgba(0, 0, 0, 0.25);
  --y2k-gel-tone-shadow: 0 2px 3px rgba(0, 0, 0, 0.3), 0 1px 1px var(--y2k-tone-button-edge), inset 0 1px 3px rgba(0, 0, 0, 0.55), inset 0 2px 3px 1px var(--y2k-tone-button-inner);
  --y2k-gel-tone-shadow-active: var(--y2k-gel-tone-shadow), 0 0 3px var(--y2k-tone-glow);
  --y2k-gel-shine: linear-gradient(rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0.3));
  --y2k-gel-glow: linear-gradient(rgba(255, 255, 255, 0), rgba(255, 255, 255, 0.5));
  --y2k-popup-shadow: 0 2px 3px rgba(0, 0, 0, 0.2), 0 1px 1px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(0, 0, 0, 0.3);

  /* ── Scrollbar (Aqua 10.x: a light grooved trough, a gel thumb toned to
     the current tone, and a paired up/down arrow box at the far end) ─── */
  --y2k-scrollbar-size: 15px;
  --y2k-scrollbar-trough: linear-gradient(to right, #cfcfcf, #e6e6e6 45%, #f2f2f2);
  --y2k-scrollbar-thumb: linear-gradient(to right, color-mix(in srgb, var(--y2k-tone) 55%, white), color-mix(in srgb, var(--y2k-tone) 18%, white) 50%, color-mix(in srgb, var(--y2k-tone) 45%, white));
  --y2k-scrollbar-thumb-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.9), inset 0 -1px 2px rgba(0, 0, 0, 0.25), 0 0 0 0.5px rgba(0, 0, 0, 0.3);
  --y2k-scrollbar-arrow: linear-gradient(to bottom, #fbfbfb, #d0d0d0);

  /* ── Traffic lights ───────────────────────────────────────────── */
  /* Aqua lights = radial-gradient sphere (bright core → mid → deep rim) + a
     white top highlight (the shine div) + a layered shadow that carries a
     white inset top rim and a crisp dark containment ring. Matches Figma
     "Apple OS X" + "Chat Aqua", ryOS, and the aqua repo. */
  --y2k-light-red: radial-gradient(circle at 50% 32%, rgb(255, 150, 150) 2%, rgb(240, 70, 70) 38%, rgb(180, 0, 0) 100%);
  --y2k-light-red-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.3), rgba(0, 0, 0, 0.2) 0 2px 3px, rgba(0, 0, 0, 0.3) 0 1px 1px, rgba(225, 70, 64, 0.5) 0 1px 1px, rgba(0, 0, 0, 0.45) 0 0 0 0.5px inset, rgba(150, 40, 30, 0.8) 0 1px 3px inset, rgba(225, 70, 64, 0.55) 0 2px 3px 1px inset;
  --y2k-light-red-glyph: rgba(130, 30, 20, 0.9);
  --y2k-light-yellow: radial-gradient(circle at 50% 32%, rgb(255, 224, 110) 2%, rgb(244, 176, 30) 38%, rgb(185, 116, 8) 100%);
  --y2k-light-yellow-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.3), rgba(0, 0, 0, 0.2) 0 2px 3px, rgba(0, 0, 0, 0.3) 0 1px 1px, rgba(223, 161, 35, 0.5) 0 1px 1px, rgba(0, 0, 0, 0.45) 0 0 0 0.5px inset, rgb(155, 78, 21) 0 1px 3px inset, rgba(241, 157, 20, 0.55) 0 2px 3px 1px inset;
  --y2k-light-yellow-glyph: rgba(130, 80, 8, 0.9);
  --y2k-light-green: radial-gradient(circle at 50% 32%, rgb(170, 240, 140) 2%, rgb(70, 190, 45) 38%, rgb(40, 125, 18) 100%);
  --y2k-light-green-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.3), rgba(0, 0, 0, 0.2) 0 2px 3px, rgba(0, 0, 0, 0.3) 0 1px 1px, rgba(59, 173, 29, 0.5) 0 1px 1px, rgba(0, 0, 0, 0.45) 0 0 0 0.5px inset, rgb(53, 91, 17) 0 1px 3px inset, rgba(98, 187, 19, 0.55) 0 2px 3px 1px inset;
  --y2k-light-green-glyph: rgba(45, 90, 18, 0.9);
  --y2k-light-off: linear-gradient(rgba(160, 160, 160, 0.625), rgba(255, 255, 255, 0.625));
  --y2k-light-off-shadow: 0 2px 3px rgba(0, 0, 0, 0.2), 0 1px 1px rgba(0, 0, 0, 0.3), inset 0 0 0 0.5px rgba(0, 0, 0, 0.3), inset 0 1px 2px rgba(0, 0, 0, 0.4), inset 0 2px 3px 1px #bbbbbb;

  /* ── Elevation ────────────────────────────────────────────────── */
  /* Aqua window drop = two casts (a tight near shadow + a wide soft far one),
     plus a white inset top rim-light on the window edge. Alpha 0.7 per ryOS. */
  --y2k-shadow-window: inset 0 1px 0 rgba(255, 255, 255, 0.7), 0 4px 10px rgba(0, 0, 0, 0.3), 0 18px 40px rgba(0, 0, 0, 0.5);
  --y2k-shadow-window-inactive: inset 0 1px 0 rgba(255, 255, 255, 0.4), 0 2px 6px rgba(0, 0, 0, 0.18), 0 8px 20px rgba(0, 0, 0, 0.22);
  --y2k-shadow-menu: 0 4px 16px rgba(0, 0, 0, 0.4);
  --y2k-shadow-dock: 0 2px 8px rgba(0, 0, 0, 0.15);
  --y2k-metal-inset: inset 0 2px 2px rgba(255, 255, 255, 0.7), inset 0 8px 14px rgba(255, 255, 255, 0.12), inset 0 -1px 0 rgba(255, 255, 255, 0.12), inset 1px 0 0 rgba(255, 255, 255, 0.15), inset -1px 0 0 rgba(255, 255, 255, 0.15);

  /* ── Metrics ──────────────────────────────────────────────────── */
  --y2k-menubar-h: 25px;
  --y2k-titlebar-h: 22px;
  --y2k-window-radius: 0.45rem;
  --y2k-button-h: 20px; /* Apple HIG 2002 p122: push button height 20px fixed (small 17px) */
  --y2k-dock-icon: 64px;
  --y2k-dock-h: 70px;

  /* ── Motion ───────────────────────────────────────────────────── */
  --y2k-ease-aqua: cubic-bezier(0.2, 0.8, 0.2, 1);
  --y2k-duration-window: 200ms;
}

/* ── Tones. Button/selection stops follow the Aqua accent formula:
      top = darken(base, .28), mid = base, bottom = lighten(base, .22),
      edge = darken(base, .2); alphas .78 / .72 so the window shows through. */
:root,
[data-tone="pink"] {
  --y2k-tone: rgb(232, 68, 154);
  --y2k-tone-button: linear-gradient(rgba(167, 49, 111, 0.78), rgba(232, 68, 154, 0.72), rgba(237, 109, 176, 0.78));
  --y2k-tone-button-edge: rgba(186, 54, 123, 0.5);
  --y2k-tone-button-inner: rgba(186, 54, 123, 0.75);
  --y2k-tone-selection: rgba(232, 68, 154, 0.88);
  --y2k-tone-selection-text: #ffffff;
  --y2k-tone-glow: rgba(232, 68, 154, 0.5);
  --y2k-tone-focus: rgba(232, 68, 154, 0.25);
  --y2k-tone-list: linear-gradient(180deg, rgb(241, 143, 194) 0%, rgb(235, 96, 169) 50%, rgb(232, 68, 154) 100%);
  --y2k-tone-text-shadow: rgba(174, 51, 116, 0.5);
  --y2k-wall-hi: rgb(242, 152, 199);
  --y2k-wall-mid: rgb(232, 68, 154);
  --y2k-wall-lo: rgb(104, 31, 69);
  /* Finder-face PNG is blue; recolour it per tone with a CSS filter. */
  --y2k-face-filter: hue-rotate(110deg) saturate(1.15);
}
[data-tone="aqua"] {
  --y2k-tone: rgb(39, 101, 202);
  --y2k-tone-button: linear-gradient(rgba(28, 73, 145, 0.78), rgba(39, 101, 202, 0.72), rgba(87, 135, 214, 0.78));
  --y2k-tone-button-edge: rgba(31, 81, 162, 0.5);
  --y2k-tone-button-inner: rgba(31, 81, 162, 0.75);
  --y2k-tone-selection: rgba(39, 101, 202, 0.88);
  --y2k-tone-selection-text: #ffffff;
  --y2k-tone-glow: rgba(39, 101, 202, 0.5);
  --y2k-tone-focus: rgba(39, 101, 202, 0.25);
  --y2k-tone-list: linear-gradient(180deg, rgb(125, 163, 223) 0%, rgb(71, 124, 210) 50%, rgb(39, 101, 202) 100%);
  --y2k-tone-text-shadow: rgba(29, 76, 152, 0.5);
  --y2k-wall-hi: rgb(136, 170, 226);
  --y2k-wall-mid: rgb(39, 101, 202);
  --y2k-wall-lo: rgb(18, 45, 91);
  --y2k-face-filter: none;
}
[data-tone="lime"] {
  --y2k-tone: rgb(127, 195, 28);
  --y2k-tone-button: linear-gradient(rgba(91, 140, 20, 0.78), rgba(127, 195, 28, 0.72), rgba(155, 208, 78, 0.78));
  --y2k-tone-button-edge: rgba(102, 156, 22, 0.5);
  --y2k-tone-button-inner: rgba(102, 156, 22, 0.75);
  --y2k-tone-selection: rgba(127, 195, 28, 0.88);
  --y2k-tone-selection-text: #000000;
  --y2k-tone-glow: rgba(127, 195, 28, 0.5);
  --y2k-tone-focus: rgba(127, 195, 28, 0.25);
  --y2k-tone-list: linear-gradient(180deg, rgb(178, 219, 119) 0%, rgb(146, 204, 62) 50%, rgb(127, 195, 28) 100%);
  --y2k-tone-text-shadow: rgba(95, 146, 21, 0.5);
  --y2k-wall-hi: rgb(185, 222, 130);
  --y2k-wall-mid: rgb(127, 195, 28);
  --y2k-wall-lo: rgb(57, 88, 13);
  --y2k-face-filter: hue-rotate(-130deg) saturate(1.05);
}
[data-tone="tangerine"] {
  --y2k-tone: rgb(232, 137, 26);
  --y2k-tone-button: linear-gradient(rgba(167, 99, 19, 0.78), rgba(232, 137, 26, 0.72), rgba(237, 163, 76, 0.78));
  --y2k-tone-button-edge: rgba(186, 110, 21, 0.5);
  --y2k-tone-button-inner: rgba(186, 110, 21, 0.75);
  --y2k-tone-selection: rgba(232, 137, 26, 0.88);
  --y2k-tone-selection-text: #000000;
  --y2k-tone-glow: rgba(232, 137, 26, 0.5);
  --y2k-tone-focus: rgba(232, 137, 26, 0.25);
  --y2k-tone-list: linear-gradient(180deg, rgb(241, 184, 118) 0%, rgb(235, 155, 60) 50%, rgb(232, 137, 26) 100%);
  --y2k-tone-text-shadow: rgba(174, 103, 20, 0.5);
  --y2k-wall-hi: rgb(242, 190, 129);
  --y2k-wall-mid: rgb(232, 137, 26);
  --y2k-wall-lo: rgb(104, 62, 12);
  --y2k-face-filter: hue-rotate(-170deg) saturate(1.2);
}
[data-tone="grape"] {
  --y2k-tone: rgb(131, 68, 196);
  --y2k-tone-button: linear-gradient(rgba(94, 49, 141, 0.78), rgba(131, 68, 196, 0.72), rgba(158, 109, 209, 0.78));
  --y2k-tone-button-edge: rgba(105, 54, 157, 0.5);
  --y2k-tone-button-inner: rgba(105, 54, 157, 0.75);
  --y2k-tone-selection: rgba(131, 68, 196, 0.88);
  --y2k-tone-selection-text: #ffffff;
  --y2k-tone-glow: rgba(131, 68, 196, 0.5);
  --y2k-tone-focus: rgba(131, 68, 196, 0.25);
  --y2k-tone-list: linear-gradient(180deg, rgb(181, 143, 220) 0%, rgb(150, 96, 205) 50%, rgb(131, 68, 196) 100%);
  --y2k-tone-text-shadow: rgba(98, 51, 147, 0.5);
  --y2k-wall-hi: rgb(187, 152, 223);
  --y2k-wall-mid: rgb(131, 68, 196);
  --y2k-wall-lo: rgb(59, 31, 88);
  --y2k-face-filter: hue-rotate(55deg) saturate(1.05);
}

/* Composite gradients are re-declared on every toned element so a swatch with
   its own data-tone renders in its own tone (custom properties resolve where
   they are declared, not where they are used). */
[data-tone] {
  --y2k-gel-tone-shadow: 0 2px 3px rgba(0, 0, 0, 0.3), 0 1px 1px var(--y2k-tone-button-edge), inset 0 1px 3px rgba(0, 0, 0, 0.55), inset 0 2px 3px 1px var(--y2k-tone-button-inner);
  --y2k-gel-tone-shadow-active: var(--y2k-gel-tone-shadow), 0 0 3px var(--y2k-tone-glow);
}

/* ── Keyframes ────────────────────────────────────────────────────── */
@keyframes y2k-window-in {
  from { scale: 0.95; opacity: 0; }
  to   { scale: 1;    opacity: 1; }
}
@keyframes y2k-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
/* The default button breathes, like Aqua's blue "Save". */
@keyframes y2k-pulse {
  0%, 100% { filter: brightness(1); }
  50%      { filter: brightness(1.12); }
}
@keyframes y2k-barber {
  from { background-position: 0 0; }
  to   { background-position: 28px 0; }
}
/* Old-web scrolling marquee: the content track slides fully left, then loops. */
@keyframes y2k-marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
/* MSN "Nudge": the toast slides up from the Dock, then shakes once. */
@keyframes y2k-nudge-in {
  0%   { transform: translateY(120%); opacity: 0; }
  60%  { transform: translateY(0);    opacity: 1; }
  68%  { transform: translate(-4px, 0); }
  76%  { transform: translate(4px, 0); }
  84%  { transform: translate(-3px, 0); }
  92%  { transform: translate(2px, 0); }
  100% { transform: translate(0, 0); }
}
@keyframes y2k-nudge-out {
  from { transform: translateY(0);    opacity: 1; }
  to   { transform: translateY(120%); opacity: 0; }
}
/* Desktop sparkle: a star glint that fades fully in then out with a scale
   pulse. Fades to 0 at the loop boundary so the desktop layer can relocate the
   glint between flashes (each twinkle appears in a new random spot). */
@keyframes y2k-twinkle {
  0%, 100% { opacity: 0; transform: scale(0.5); }
  50%      { opacity: 1; transform: scale(1); }
}

/* ── Materials ───────────────────────────────────────────────────── */

/* Brushed aluminum (iTunes / Finder in Tiger). Neutral, so a static texture. */
.y2k-metal {
  background-color: #c9c9c9;
  background-image: var(--y2k-metal);
  background-size: 512px 96px;
}

/* Gel wordmark text: tone gradient clipped to glyphs. */
.y2k-gel-text {
  background: var(--y2k-tone-list);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 0 rgba(255, 255, 255, 0.7));
}

@media (prefers-reduced-motion: reduce) {
  [data-default="true"] { animation: none !important; }
}
